import React from 'react';
import { FaTimes } from 'react-icons/fa';
import { FaBars } from 'react-icons/fa6';
import { Drawer } from '~/components/ui/drawer';
import { IconButton } from '~/components/ui/icon-button';

interface LazyDrawerProps {
  openButtonLabel: string;
  closeButtonLabel: string;
  rightSidebarContent?: (props: { close: () => void }) => React.ReactNode;
}

export default function LazyDrawer({
  openButtonLabel,
  closeButtonLabel,
  rightSidebarContent
}: LazyDrawerProps) {
  return (
    <Drawer.Root>
      <Drawer.Trigger asChild>
        <IconButton variant="ghost" aria-label={openButtonLabel}>
          <FaBars />
        </IconButton>
      </Drawer.Trigger>
      <Drawer.Backdrop />
      <Drawer.Positioner>
        <Drawer.Content>
          <Drawer.CloseTrigger asChild position="absolute" top="3" right="4">
            <IconButton variant="ghost" aria-label={closeButtonLabel}>
              <FaTimes />
            </IconButton>
          </Drawer.CloseTrigger>
          <Drawer.Body>
            <Drawer.Context>
              {(ctx) => {
                return (
                  rightSidebarContent && rightSidebarContent({ close: () => ctx.setOpen(false) })
                );
              }}
            </Drawer.Context>
          </Drawer.Body>
        </Drawer.Content>
      </Drawer.Positioner>
    </Drawer.Root>
  );
}
